package com.dappunq.service;
import com.dappunq.dto.valuation.*; import com.dappunq.model.valuation.*; import com.dappunq.persistence.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class HoldingsValuationService { final HoldingRepository holdings; final ValuationHistoryRepository history; final PlayerRepository players; final StrategyConfigRepository configs; final ValuationPersistenceMapper mapper; final PlayerValuationCalculator calculator=new PlayerValuationCalculator(); public HoldingsValuationService(HoldingRepository h,ValuationHistoryRepository x,PlayerRepository p,StrategyConfigRepository c,ValuationPersistenceMapper m){holdings=h;history=x;players=p;configs=c;mapper=m;} @Transactional public int revalue(Long userId,StrategyConfigEntity ce,ExecutionType type){List<PlayerEntity> snapshot=players.findAll(); StrategyConfig c=new StrategyConfig(ce.getEstrategia(),mapper.read(ce.getPesos())); int n=0; String window=LocalDate.now().toString()+"-"+type; for(HoldingEntity h:holdings.findByUserId(userId)){var v=calculator.calculate(h.getPlayer(),c,snapshot);h.valuate(v);holdings.save(h);history.save(new ValuationHistoryEntity(h.getUser(),h.getPlayer(),h.getTokens(),v,c.strategy(),window,type));n++;} return n;} public List<HoldingResponse> list(Long id){return holdings.findByUserId(id).stream().map(h->new HoldingResponse(h.getId(),h.getUser().getId(),h.getPlayer().getId(),h.getTokens(),h.getValorTotal(),h.getValorUnitario())).toList();} public List<HoldingHistoryResponse> history(Long id){return history.findByUserIdOrderByEjecutadoEnDesc(id).stream().map(h->new HoldingHistoryResponse(h.getUser().getId(),h.getPlayer().getId(),h.getTokens(),h.getValorUnitario(),h.getValorTotal(),h.getEstrategia(),h.getEjecutadoEn(),h.getTipoEjecucion())).toList();} }
